"use client";
import{useEffect,useState}from"react";import{defaults,type Banner}from"../../../lib/banner-types";
export default function AdminBanner(){const[b,setB]=useState<Banner>(defaults),[msg,setMsg]=useState("");useEffect(()=>{fetch("/api/banner").then(r=>r.json()).then(setB)},[]);const u=(k:keyof Banner,v:string|boolean)=>setB(x=>({...x,[k]:v}));async function save(){const r=await fetch("/api/banner",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});setMsg(r.ok?"بنر ذخیره شد.":"ذخیره انجام نشد.")}return <main className="admin"><div className="adminHead"><h1>مدیریت بنر تبلیغاتی</h1><a href="/admin">بازگشت</a></div><div className="editor"><section><label><input type="checkbox" checked={b.enabled} onChange={e=>u("enabled",e.target.checked)}/> نمایش بنر</label><label>لینک تصویر<input value={b.image} onChange={e=>u("image",e.target.value)}/></label><label>عبارت کوچک<input value={b.eyebrow} onChange={e=>u("eyebrow",e.target.value)}/></label><label>تیتر<input value={b.title} onChange={e=>u("title",e.target.value)}/></label><label>توضیح<textarea value={b.text} onChange={e=>u("text",e.target.value)}/></label><label>متن دکمه<input value={b.buttonText} onChange={e=>u("buttonText",e.target.value)}/></label><label>لینک دکمه<input value={b.buttonLink} onChange={e=>u("buttonLink",e.target.value)}/></label></section><button className="save" onClick={save}>ذخیره بنر</button><p className="status">{msg}</p></div></main>}
